from abc import ABC
from collections.abc import Callable, Generator
from functools import wraps
from typing import Any, Generic, TypeVar, cast
import inspect

from typing_extensions import ParamSpec

from .error import EffectError


_TInner = TypeVar("_TInner")
_TOuter = TypeVar("_TOuter")
_P = ParamSpec("_P")


class Builder(Generic[_TInner, _TOuter], ABC):
    """Effect builder."""

    def bind(self, xs: _TOuter, fn: Callable[[Any], _TOuter]) -> _TOuter:
        raise NotImplementedError("Builder does not implement a bind method")

    def return_(self, x: _TInner) -> _TOuter:
        raise NotImplementedError("Builder does not implement a return method")

    def return_from(self, xs: _TOuter) -> _TOuter:
        raise NotImplementedError("Builder does not implement a return from method")

    def combine(self, xs: _TOuter, ys: _TOuter) -> _TOuter:
        """Used for combining multiple statements in the effect."""
        raise NotImplementedError("Builder does not implement a combine method")

    def zero(self) -> _TOuter:
        """Zero effect.

        Called if the effect raises StopIteration without a value, i.e
        returns None.
        """
        raise NotImplementedError("Builder does not implement a zero method")

    def delay(self, fn: Callable[[], _TOuter]) -> _TOuter:
        """Default implementation evaluates the given function."""
        return fn()

    def run(self, xs: _TOuter) -> _TOuter:
        """Default implementation assumes the result is already evaluated."""
        return xs

    def _send(
        self,
        gen: Generator[Any, Any, Any],
        done: list[bool],
        value: _TInner | None = None,
    ) -> _TOuter:
        try:
            # Check if this is an async generator
            if inspect.isasyncgen(gen):
                # For async generators, we need to use __anext__() instead of send()
                try:
                    yielded = gen.__anext__()
                    # If yielded is awaitable, we should await it
                    if hasattr(yielded, '__await__'):
                        # This is a bit tricky - we can't await here in sync context
                        # So we'll let the caller handle this appropriately
                        return self.return_(yielded)
                    else:
                        return self.return_(yielded)
                except StopAsyncIteration as stop_ex:
                    done.append(True)
                    # Return of a value in the generator produces StopAsyncIteration with a value
                    # We need to be careful about how we access the value attribute
                    try:
                        if hasattr(stop_ex, 'value') and stop_ex.value is not None:
                            return self.return_(stop_ex.value)
                        elif hasattr(stop_ex, 'value') and stop_ex.value is None:
                            # StopAsyncIteration with None value should raise to trigger zero() handling
                            raise
                        # If no 'value' attribute, re-raise as-is
                        raise
                    except AttributeError:
                        # Handle case where StopAsyncIteration doesn't have 'value' attribute
                        raise
            else:
                # Check if the generator supports send method (i.e. is a true generator)
                # If it doesn't support send, it's likely an iterator (like list_iterator) 
                # that we should handle with next() instead
                try:
                    yielded = gen.send(value)
                    return self.return_(yielded)
                except AttributeError as ex:
                    if "'object' object has no attribute 'send'" in str(ex) or "has no attribute 'send'" in str(ex):
                        # Handle iterators that don't support send (like list_iterator)
                        try:
                            yielded = next(gen)
                            return self.return_(yielded)
                        except StopIteration as stop_ex:
                            done.append(True)
                            # Return of a value in the generator produces StopIteration with a value
                            # We need to be careful about how we access the value attribute
                            try:
                                if hasattr(stop_ex, 'value') and stop_ex.value is not None:
                                    return self.return_(stop_ex.value)
                                elif hasattr(stop_ex, 'value') and stop_ex.value is None:
                                    # StopIteration with None value should raise to trigger zero() handling
                                    raise
                                # If no 'value' attribute, re-raise as-is
                                raise
                            except AttributeError:
                                # Handle case where StopIteration doesn't have 'value' attribute
                                raise
                    raise  # Re-raise if it's a different AttributeError
        except EffectError as error:
            # Effect errors (Nothing, Error, etc) short circuits the processing so we
            # set `done` to `True` here.
            done.append(True)
            # get value from exception
            value = error.args[0]
            return self.return_from(cast("_TOuter", value))
        except StopIteration as ex:
            done.append(True)
            # Return of a value in the generator produces StopIteration with a value
            # We need to be careful about how we access the value attribute
            try:
                if hasattr(ex, 'value') and ex.value is not None:
                    return self.return_(ex.value)
                elif hasattr(ex, 'value') and ex.value is None:
                    # StopIteration with None value should raise to trigger zero() handling
                    raise
                # If no 'value' attribute, re-raise as-is
                raise
            except AttributeError:
                # Handle case where StopIteration doesn't have 'value' attribute
                raise
        except RuntimeError:
            done.append(True)
            raise StopIteration

    def __call__(
        self,
        fn: Callable[
            _P,
            Generator[_TInner | None, _TInner, _TInner | None] | Generator[_TInner | None, None, _TInner | None],
        ],
    ) -> Callable[_P, _TOuter]:
        """Option builder.

        Enables the use of computational expressions using coroutines.
        Thus inside the coroutine the keywords `yield` and `yield from`
        reassembles `yield` and `yield!` from F#.

        Args:
            fn: A function that contains a computational expression and
                returns either a coroutine, generator or an option.

        Returns:
            A `builder` function that can wrap coroutines into builders.
        """

        @wraps(fn)
        def wrapper(*args: _P.args, **kw: _P.kwargs) -> _TOuter:
            gen = fn(*args, **kw)
            done: list[bool] = []

            result: _TOuter | None = None

            def binder(value: Any) -> _TOuter:
                ret = self._send(gen, done, value)

                # Delay every result except the first
                if result is not None:
                    return self.delay(lambda: ret)
                return ret

            try:
                result = self._send(gen, done)

                while not done[0] if done else False:
                    cont = self.bind(result, binder)

                    # Combine every result except the first
                    if result is None:
                        result = cont
                    else:
                        result = self.combine(result, cont)
            except StopIteration:
                # This catches StopIteration that was raised by our own code
                # We should check if we actually got a value or not
                pass

            # If anything returns `None` (i.e raises StopIteration without a value) then
            # we expect the effect to have a zero method implemented.
            # But we also need to check if we got StopIteration with no value
            if result is None:
                result = self.zero()

            return self.run(result)

        return wrapper
